     1	"use client";
     2	
     3	import { useEffect, useRef, useState } from "react";
     4	
     5	/**
     6	 * Defers rendering a subtree until it is near the viewport.
     7	 *
     8	 * `next/dynamic` alone is not enough. It splits the chunk, but the import
     9	 * still fires the moment the parent renders — which is during hydration — so
    10	 * six deferred blocks on the project page meant six chunks downloading and
    11	 * executing while the browser was trying to settle the first screen. That work
    12	 * pushed LCP out to roughly where TTI landed, about 4.8s.
    13	 *
    14	 * Wrapping each block in this component moves the import to the point where
    15	 * the visitor is actually approaching it. Nothing below the fold competes with
    16	 * the paint above it.
    17	 *
    18	 * The placeholder must reserve the block's height, or deferring the mount
    19	 * simply trades a slow LCP for a layout shift.
    20	 */
    21	export function LazyMount({
    22	  children,
    23	  placeholder,
    24	  /** How far ahead to start loading. Enough to feel instant when scrolling. */
    25	  rootMargin = "400px",
    26	}: {
    27	  children: React.ReactNode;
    28	  placeholder: React.ReactNode;
    29	  rootMargin?: string;
    30	}) {
    31	  const ref = useRef<HTMLDivElement>(null);
    32	  const [mounted, setMounted] = useState(false);
    33	
    34	  useEffect(() => {
    35	    const node = ref.current;
    36	    if (!node) return;
    37	
    38	    // No IntersectionObserver (very old browsers): render on the next tick
    39	    // rather than leave the visitor looking at a skeleton forever. Deferred
    40	    // by a timeout so it is a callback rather than a synchronous cascade.
    41	    if (typeof IntersectionObserver === "undefined") {
    42	      const timer = setTimeout(() => setMounted(true), 0);
    43	      return () => clearTimeout(timer);
    44	    }
    45	
    46	    const observer = new IntersectionObserver(
    47	      ([entry]) => {
    48	        if (entry.isIntersecting) {
    49	          setMounted(true);
    50	          observer.disconnect();
    51	        }
    52	      },
    53	      { rootMargin },
    54	    );
    55	
    56	    observer.observe(node);
    57	    return () => observer.disconnect();
    58	  }, [rootMargin]);
    59	
    60	  return <div ref={ref}>{mounted ? children : placeholder}</div>;
    61	}
    62	
    63	/** Height-reserving skeleton, so deferring a block costs no layout shift. */
    64	export function Skeleton({ className }: { className: string }) {
    65	  return <div className={`bg-card animate-pulse border border-border ${className}`} aria-hidden />;
    66	}
