     1	"use client";
     2	
     3	import { useEffect } from "react";
     4	import Lenis from "lenis";
     5	import "lenis/dist/lenis.css";
     6	
     7	import { useReducedMotionPreference } from "@/components/providers/reduced-motion-provider";
     8	
     9	/**
    10	 * Weighted smooth scroll — the single cheapest signal that a site was built
    11	 * rather than assembled.
    12	 *
    13	 * Deliberately skipped on two paths: when the visitor asks for reduced motion,
    14	 * and on coarse pointers, where hijacking native momentum scroll costs INP on
    15	 * the low-end Android hardware much of this audience browses on (CLAUDE.md §6).
    16	 */
    17	export function LenisProvider() {
    18	  const reducedMotion = useReducedMotionPreference();
    19	
    20	  useEffect(() => {
    21	    if (reducedMotion) return;
    22	
    23	    const isTouch = window.matchMedia("(pointer: coarse)").matches;
    24	    if (isTouch) return;
    25	
    26	    const lenis = new Lenis({ lerp: 0.1, wheelMultiplier: 1 });
    27	
    28	    let frame = 0;
    29	    const raf = (time: number) => {
    30	      lenis.raf(time);
    31	      frame = requestAnimationFrame(raf);
    32	    };
    33	    frame = requestAnimationFrame(raf);
    34	
    35	    return () => {
    36	      cancelAnimationFrame(frame);
    37	      lenis.destroy();
    38	    };
    39	  }, [reducedMotion]);
    40	
    41	  return null;
    42	}
