     1	"use client";
     2	
     3	import { createContext, useCallback, useContext, useSyncExternalStore } from "react";
     4	
     5	const ReducedMotionContext = createContext(false);
     6	
     7	const QUERY = "(prefers-reduced-motion: reduce)";
     8	
     9	/**
    10	 * Single source of truth for `prefers-reduced-motion`.
    11	 *
    12	 * Every motion decision in the app reads this: Lenis stays off, GSAP degrades
    13	 * to fades, and the WebGL hero swaps for a static image. CSS handles its own
    14	 * half via the media query in globals.css; this covers the JS half.
    15	 *
    16	 * Read through `useSyncExternalStore` rather than an effect, so the value is
    17	 * correct on the first client render — no flash of motion before the
    18	 * preference is detected.
    19	 */
    20	export function ReducedMotionProvider({
    21	  children,
    22	}: {
    23	  children: React.ReactNode;
    24	}) {
    25	  const reduced = useReducedMotionQuery();
    26	
    27	  return (
    28	    <ReducedMotionContext.Provider value={reduced}>
    29	      {children}
    30	    </ReducedMotionContext.Provider>
    31	  );
    32	}
    33	
    34	function useReducedMotionQuery(): boolean {
    35	  const subscribe = useCallback((onChange: () => void) => {
    36	    const query = window.matchMedia(QUERY);
    37	    query.addEventListener("change", onChange);
    38	    return () => query.removeEventListener("change", onChange);
    39	  }, []);
    40	
    41	  return useSyncExternalStore(
    42	    subscribe,
    43	    () => window.matchMedia(QUERY).matches,
    44	    // Server snapshot: assume motion is allowed, then correct on hydration.
    45	    () => false,
    46	  );
    47	}
    48	
    49	/** Read the visitor's motion preference from any client component. */
    50	export function useReducedMotionPreference(): boolean {
    51	  return useContext(ReducedMotionContext);
    52	}
