     3	import { LazyMotion } from "framer-motion";
     4	
     5	import loadDomAnimation from "@/components/motion/motion-features";
     6	
     7	/**
     8	 * Wraps the app in a single LazyMotion boundary.
     9	 *
    10	 * One boundary means the `domAnimation` feature bundle is fetched once and
    11	 * shared by every `m.*` element on the page, instead of each reveal dragging
    12	 * its own copy of the animation runtime into the initial chunk.
    13	 *
    14	 * `strict` makes the tree throw if anyone reaches for the full `motion`
    15	 * component by mistake — which is exactly the regression this guards against.
    16	 */
    17	export function MotionProvider({ children }: { children: React.ReactNode }) {
    18	  return (
    19	    <LazyMotion features={loadDomAnimation} strict>
    20	      {children}
    21	    </LazyMotion>
    22	  );
    23	}
=====FILE: components/motion/motion-features.ts=====
     1	/**
     2	 * Framer Motion feature bundle, loaded lazily.
     3	 *
     4	 * Importing `motion` pulls in every feature — layout animation, drag, gestures,
     5	 * SVG path morphing — whether a page uses them or not. This site only ever
     6	 * animates opacity and transform, so it loads `domAnimation` (the smallest
     7	 * feature set) asynchronously through `LazyMotion`, and components use the `m`
     8	 * primitive rather than `motion`.
     9	 *
    10	 * That combination is roughly a third of the full package, and it is what makes
    11	 * Framer affordable on pages carrying a dozen reveals (CLAUDE.md §4, §15).
    12	 */
    13	export default async function loadDomAnimation() {
    14	  const { domAnimation } = await import("framer-motion");
    15	  return domAnimation;
    16	}
