     1	"use client";
     2	
     3	import { Component, type ReactNode } from "react";
     4	
     5	/**
     6	 * Catches anything a WebGL subtree throws.
     7	 *
     8	 * A lost context, a driver fault or an out-of-memory kill inside a Three.js
     9	 * scene would otherwise unmount the whole route. Every scene on this site sits
    10	 * over content that already works, so the correct response to a failure is to
    11	 * render nothing and let that content stand.
    12	 */
    13	export class WebGLBoundary extends Component<
    14	  { children: ReactNode; fallback?: ReactNode },
    15	  { failed: boolean }
    16	> {
    17	  state = { failed: false };
    18	
    19	  static getDerivedStateFromError() {
    20	    return { failed: true };
    21	  }
    22	
    23	  componentDidCatch(error: unknown) {
    24	    // Worth knowing about, never worth interrupting the visitor for.
    25	    console.warn("[webgl] scene failed, falling back", error);
    26	  }
    27	
    28	  render() {
    29	    if (this.state.failed) return this.props.fallback ?? null;
    30	    return this.props.children;
    31	  }
    32	}
