   153	 * orientations and can carry a resale premium; the rest are stated plainly
   154	 * rather than dressed up (CLAUDE.md §2).
   155	 */
   156	export function vastuNote(facing: Facing): string {
   157	  switch (facing) {
   158	    case "East":
   159	      return "East-facing. The most sought-after orientation in Gujarat — morning light through the main rooms, and the entry away from the south-west.";
   160	    case "North-East":
   161	      return "North-East facing. Considered the most auspicious corner in Vastu, and the orientation buyers ask for first.";
   162	    case "North":
   163	      return "North-facing. Well regarded, with even light through the day and no harsh afternoon sun on the living areas.";
   164	    case "West":
   165	      return "West-facing. Less sought-after than east, and warmer in the afternoon, which is usually reflected in the price.";
   166	    case "South":
   167	    case "South-West":
   168	      return "South-facing. Not the preferred orientation in Vastu terms; we mention it because you would find out anyway.";
   169	    default:
   170	      return `${facing} facing.`;
   171	  }
   172	}

