   103	      { name: "Master Suite", x: 17, y: 0, w: 15, h: 9, share: 0.18, kind: "bedroom" },
   104	      { name: "Bedroom 2", x: 17, y: 9, w: 15, h: 6, share: 0.12, kind: "bedroom" },
