   107	      { name: "Study", x: 25, y: 21, w: 7, h: 5, share: 0.08, kind: "bedroom" },
   108	    ],
   109	  },
   110	};
   111	
   112	/** Resolves a layout from a configuration string such as "3 BHK". */
   113	export function getFloorPlan(bhk: string): FloorPlan {
   114	  const rooms = parseInt(bhk, 10);
   115	  const key = `${Math.min(Math.max(rooms || 3, 2), 5)}bhk`;
   116	  return PLANS[key] ?? PLANS["3bhk"];
   117	}
   118	
   119	/**
   120	 * Prints a room's dimensions in metres, derived from its share of the unit's
   121	 * real carpet area. The proportions are schematic; the areas are not.
   122	 */
   123	export function roomDimensions(room: Room, carpetAreaSqFt: number): string {
   124	  const areaSqM = carpetAreaSqFt * room.share * 0.092903;
   125	  // Recover a plausible rectangle from the area using the drawn aspect ratio.
   126	  const aspect = room.w / room.h;
   127	  const height = Math.sqrt(areaSqM / aspect);
   128	  const width = areaSqM / height;
   129	  return `${width.toFixed(1)} × ${height.toFixed(1)} m`;
   130	}
   131	
   132	/**
   133	 * Degrees to rotate the compass needle so north points correctly relative to
   134	 * the plan, given which way the home faces. The plan is drawn with its entry
   135	 * on the left, so an east-facing home has north at the top.
   136	 */
   137	export function compassRotation(facing: Facing): number {
   138	  const bearings: Record<Facing, number> = {
   139	    East: 0,
   140	    "North-East": -45,
   141	    North: -90,
   142	    "North-West": -135,
   143	    West: 180,
   144	    "South-West": 135,
   145	    South: 90,
   146	    "South-East": 45,
   147	  };
   148	  return bearings[facing];
   149	}
   150	
   151	/**
   152	 * Vastu commentary for a facing. East and north-east are the prized
   153	 * orientations and can carry a resale premium; the rest are stated plainly
   154	 * rather than dressed up (CLAUDE.md §2).
   155	 */
   156	export function vastuNote(facing: Facing): string {
   157	  switch (facing) {
   158	    case "East":
   159	      return "East-facing. The most sought-after orientation in Gujarat — morning light through the main rooms, and the entry away from the south-west.";
   160	    case "North-East":
   161	      return "North-East facing. Considered the most auspicious corner in Vastu, and the orientation buyers ask for first.";
   162	    case "North":
   163	      return "North-facing. Well regarded, with even light through the day and no harsh afternoon sun on the living areas.";
   164	    case "West":
   165	      return "West-facing. Less sought-after than east, and warmer in the afternoon, which is usually reflected in the price.";
   166	    case "South":
   167	    case "South-West":
   168	      return "South-facing. Not the preferred orientation in Vastu terms; we mention it because you would find out anyway.";
   169	    default:
   170	      return `${facing} facing.`;
   171	  }
   172	}

